function validate([s, t]) {
  if (s.length < 1 || s.length > 26) return 's needs 1 to 26 letters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase English letters.';
  if (new Set(s).size !== s.length) return 'Each letter appears at most once in s.';
  if (t.length !== s.length || [...t].sort().join('') !== [...s].sort().join('')) return 't must hold exactly the letters of s, rearranged.';
  return null;
}

