function findPermutationDifference(s, t) {
  // indexInS maps each letter to its index in s.
  const indexInS = new Map();
  for (let i = 0; i < s.length; i++) {
    indexInS.set(s[i], i);
  }
  let difference = 0;
  for (let j = 0; j < t.length; j++) {
    const i = indexInS.get(t[j]);
    difference += Math.abs(i - j);
  }
  return difference;
}

brute:
function findPermutationDifference(s, t) {
  // For every letter of s, scan all of t to find where that letter went.
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = 0; j < t.length; j++) {
      if (t[j] === s[i]) total += Math.abs(i - j);
    }
  }
  return total;
}

