function generate(rand, size) {
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  // s takes n distinct letters in random order; 26 is the most a string of distinct lowercase letters can hold.
  const n = size === 'large' ? 26 : 1 + Math.floor(rand() * 8);
  const s = shuffle('abcdefghijklmnopqrstuvwxyz'.split('')).slice(0, n);
  // t is s unchanged, s reversed, or a random rearrangement of s.
  const r = size === 'large' ? 1 : rand();
  const t = r < 0.15 ? s.slice() : r < 0.3 ? s.slice().reverse() : shuffle(s.slice());
  return [s.join(''), t.join('')];
}
